function geoBound(g){let b=[Infinity,Infinity,-Infinity,-Infinity];function walk(a){if(typeof a[0]==='number'){b=[Math.min(b[0],a[0]),Math.min(b[1],a[1]),Math.max(b[2],a[0]),Math.max(b[3],a[1])];}else a.forEach(walk);}walk(g.coordinates);return b;}
function overlaps(a,b){return a[0]<=b[2]&&a[2]>=b[0]&&a[1]<=b[3]&&a[3]>=b[1];}
function ringContains(x,y,r){let inside=false;for(let i=0,j=r.length-1;i<r.length;j=i++){const a=r[i],b=r[j],dx=b[0]-a[0],dy=b[1]-a[1],cross=(x-a[0])*dy-(y-a[1])*dx;if(Math.abs(cross)<1e-11&&x>=Math.min(a[0],b[0])&&x<=Math.max(a[0],b[0])&&y>=Math.min(a[1],b[1])&&y<=Math.max(a[1],b[1]))return true;if((a[1]>y)!==(b[1]>y)&&x<(b[0]-a[0])*(y-a[1])/(b[1]-a[1])+a[0])inside=!inside;}return inside;}
function contains(g,x,y){const polys=g.type==='Polygon'?[g.coordinates]:g.type==='MultiPolygon'?g.coordinates:[];return polys.some(p=>ringContains(x,y,p[0])&&!p.slice(1).some(r=>ringContains(x,y,r)));}
function km(x1,y1,x2,y2){const d=Math.PI/180,a=Math.sin((y2-y1)*d/2)**2+Math.cos(y1*d)*Math.cos(y2*d)*Math.sin((x2-x1)*d/2)**2;return 6371.0088*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a));}
