function setMarker(x,y){if(!map||!Number.isFinite(x)||!Number.isFinite(y))return;if(marker)marker.remove();marker=new maplibregl.Marker({color:'#143d4d'}).setLngLat([x,y]).addTo(map);}
async function climateFor(c){if(!c.domain)return null;const dep=c.department||c.code.slice(0,3);if(!meta.climate_departments.includes(dep))return null;return (await data(`climate/${dep}.json`))[c.code]||null;}
async function selectCity(code,fly=true,remember=true){const city=cities.find(c=>c.code===code);if(!city)return;const token=++state.request;if(remember&&state.place)state.history.push({...state.place});state.place={...city,kind:'commune'};state.selectedSite=null;state.climate=null;$('#place-panel').innerHTML='<div class="loading">Lecture de la fiche territoriale…</div>';$('#search-results').hidden=true;$('#search').setAttribute('aria-expanded','false');setMarker(city.longitude,city.latitude);if(fly&&map)map.flyTo({center:[city.longitude,city.latitude],zoom:11,duration:1100});try{const c=await climateFor(city);if(token!==state.request)return;state.climate=c;renderPlace();setHash();onMobile();}catch(e){if(token!==state.request)return;renderPlace();notify('Fiche climatique indisponible : '+e.message);} }
