function addCompare(){if(!state.place?.code)return notify('Choisissez une commune.');if(state.comparison.some(c=>c.code===state.place.code))return notify('Cette commune est déjà dans la comparaison.');if(state.comparison.length>=4)return notify('Quatre lieux au maximum. Retirez un lieu dans Comparer.');const c=cities.find(c=>c.code===state.place.code);state.comparison.push({ ...c,climate:state.climate });$('#compare-count').textContent=state.comparison.length;notify(c.name+' ajouté à la comparaison');}
