 $$('[data-remove]').forEach(b=>b.onclick=()=>{state.comparison=items.filter(x=>x.code!==b.dataset.remove);$('#compare-count').textContent=state.comparison.length;showComparison();});$('#heat-limit').onchange=e=>{thresholdHeat=Math.min(366,Math.max(0,Number(e.target.value)||0));showComparison();};$('#require-flood').onchange=e=>{requireFlood=e.target.checked;notify('Sans étude locale applicable, ce critère reste « à documenter ».');};$('#priority').value=priority;$('#priority').onchange=e=>{priority=e.target.value;priorities={all:['S1','S2','R4','R5','AG1','R3'],heat:['S1','S2'],dry:['R5','AG1'],fire:['R4'],coast:['R3']}[priority];showComparison();};$('#why').onclick=()=>{modal('Pourquoi ces résultats ?',`<p>Aucune pondération ni normalisation cachée. Chaque case lit le même indicateur, la même saison et le même horizon dans SQLite. Les médianes et bornes sont celles de Météo-France.</p><p>La contrainte compare la médiane des jours très chauds à votre seuil (${thresholdHeat} j/an). Les données manquantes produisent « à documenter ». Une borne haute dépassant votre seuil reste à examiner dans le tableau ; le critère sur la médiane ne constitue aucune garantie.</p><p>Source : ${link('https://climadiag-commune.meteofrance.com/','Climadiag Commune')}. Références territoriales conservées dans l’export. Aucune photo ou donnée fossile n’intervient dans cette comparaison.</p><button id="back-comparison" class="outline">Revenir au tableau</button>`);$('#back-comparison').onclick=showComparison;};$('#export-compare').onclick=()=>download('ChronoTerre_comparaison.json',{generated_at:new Date().toISOString(),horizon:state.horizon,climate_columns:meta.climate_columns,scenario:state.horizon==='ref'?'reference':'TRACC',criteria:priorities,heat_threshold:thresholdHeat,require_local_flood_study:requireFlood,places:items.map(c=>({commune:c.code,name:c.name,climate:c.climate})),indicator_definitions:meta.indicators,source:meta.raw.climadiag,limits:meta.coverage});$('#print-compare').o