function showSources(){modal('Sources & méthode',`<p><b>ChronoTerre — France</b> relie des lieux à des données de producteurs publics et à des publications. Fossiles, climat et réglementation restent trois informations distinctes.</p><p class="web-mode">Instantané national du ${new Date(meta.snapshot_at).toLocaleString('fr-FR')} produit par le pipeline Python / SQLite. Adresses et urbanisme : consultations des services officiels à la demande. Aucune mise à jour automatique n’est programmée.</p><div class="source-grid">${meta.sources.map(s=>`<article class="source-card"><h3>${esc(s.producer)}</h3><p>${esc(s.license)}</p><p>${esc(s.limits)}</p>${link(s.url,'Producteur et documentation')}</article>`).join('')}</div><h3>Des échelles différentes</h3><p>La carte peut atteindre la rue ; cela n’affine pas une projection climatique de maille 8 km. Les fossiles n’expliquent pas le risque futur. Une concentration d’occurrences peut refléter l’effort de publication, jamais un comptage d’animaux.</p><h3>Vie privée</h3><p>La recherche d’adresse est envoyée à l’IGN quand elle est nécessaire. Aucun historique d’adresses n’est conservé par ChronoTerre. Les favoris restent sur cet appareil ; les liens partagés portent sur la commune uniquement.</p><button id="source-export" class="outline">Télécharger le registre de provenance</button>`);$('#source-export').onclick=()=>download('ChronoTerre_sources.json',{sources:meta.sources,raw:meta.raw,coverage:meta.coverage});}
function showCoverage(){modal('Ce qu’on sait / ce qui manque',`<p>Les compteurs sont calculés dans la base nationale après les contrôles, sans réutiliser ceux de la V1.</p><div class="stat-grid"><div class="mini-stat"><div class="label">Communes recherchables</div><div class="value">${fmt(meta.counts.commune,0)}</div></div><div class="mini-stat"><div class="label">Fiches climatiques</div><div class="value">${fmt(meta.counts.climate_place,0)}</div></div><div class="mini-stat"><div class="label">Occurrences fossiles retenues</div><div class="value">${fmt(meta.counts.fossil_occurrence,0)}</div></div><div class="mini-stat"><div class="label">Collections fossilifères</div><div class="value">${fmt(meta.counts.fossil_site,0)}</div></div></div><div class="table-wrap"><table><thead><tr><th>Information</th><th>Couverture réelle</th></tr></thead><tbody>${Object.entries(meta.coverage).map(([k,v])=>`<tr><th>${esc(k)}</th><td>${esc(v)}</td></tr>`).join('')}<tr><th>+50 ans</th><td>2026 + 50 = 2076. Aucune interpolation entre 2050 et 2100 ; combinaison désactivée.</td></tr><tr><th>Galeries</th><td>Quelques taxons illustrés et attribués. Pas de photo locale de spécimen garantie ; les fiches sans image l’indiquent. Photographie aérienne en ligne seulement.</td></tr><tr><th>Autres données</th><td>Pas de débits Explore2, d’érosion Cerema, de carte d’îlot de chaleur ni de séismes/radon intégrés. Les liens vers les producteurs restent disponibles.</td></tr></tbody></table></div><p>Les cadres blancs ne signifient pas « sans risque ». L’examen d’un bien et les vérifications en mairie restent nécessaires.</p><button id="show-quality" class="outline">Rapport de qualité réel</button>`);$('#show-quality').onclick=async()=>{const q=await data('quality.json');modal('Qualité des données',`<p>Statut ${esc(q.status)}. Intégrité SQLite : ${esc(q.integrity)}. Fichiers bruts vérifiés : ${q.raw_verified}.</p><table><thead><tr><th>Règle</th><th>Condition</th><th>Échecs</th><th>Action</th></tr></thead><tbody>${q.rules.map(r=>`<tr><td>${esc(r.id+' '+r.name)}</td><td>${esc(r.condition)}</td><td>${r.failures}</td><td>${esc(r.action)}</td></tr>`).join('')}</tbody></table><p>Empreinte du contenu : <code>${esc(q.semantic_sha256)}</code></p>`);};}
async function setMode(mode){if(mode==='living')$('#legend').innerHTML='<b>Informations cartographiées</b><span><i class="blue"></i>Enveloppes de crue · Toulouse</span><span><i class="ochre"></i>Argiles · secteur Bordeaux</span><small>Zonages actuels, indépendants de l’horizon climatique</small>';state.mode=mode;state.selectedSite=null;$('#living').classList.toggle('active',mode==='living');$('#past').classList.toggle('active',mode==='past');$('#past-filters').hidden=mode!=='past';$('#horizons').hidden=mode==='past';$('#map-caption').hidden=mode==='past';renderPlace();setHash();if(mapReady)map.getSource('fossils').setData({type:'FeatureCollection',features:[]});if(mode==='past')await updateFossils();}
